"""Shared Pixelflux 2.2.3 runtime for full-frame H.264, H.265 and AV1."""
import importlib
import re
import struct
import threading

_runtime = None


def runtime():
    global _runtime
    if _runtime is None:
        try:
            _runtime = importlib.import_module("pixelflux")
        except ImportError as exc:
            raise RuntimeError("Pixelflux 2.2.3 runtime is not installed") from exc
    return _runtime


def available():
    try:
        return "h265" in runtime().SOFTWARE_ENCODERS
    except (ImportError, OSError, RuntimeError):
        return False


def packet(payload, frame_id, width, height):
    """Legacy geometry/ACK framing, distinct tag 5 and an HEVC Annex-B AU."""
    keyframe = False
    for start in re.finditer(b"\x00\x00(?:\x00)?\x01", payload):
        if start.end() >= len(payload):
            break
        nal_type = (payload[start.end()] >> 1) & 63
        if nal_type <= 31:
            keyframe = 16 <= nal_type <= 21
            break
    return struct.pack("!BBHHHH", 5, int(keyframe), frame_id & 65535, 0, width, height) + payload


class PrivateLiveControls:
    def update_paint_over(self, enabled):
        settings = self._settings
        previous = settings.use_paint_over_quality
        settings.use_paint_over_quality = enabled
        try:
            self.capture.update_tunables(settings)
        except Exception:
            settings.use_paint_over_quality = previous
            raise

    def update_framerate(self, fps):
        self.capture.update_framerate(float(fps))

    def update_quality(self, legacy):
        settings = self._settings
        for name in ('crf', 'paintover_crf', 'paintover_burst_frames'):
            setattr(settings, 'video_' + name, getattr(legacy, 'h264_' + name))
        settings.use_paint_over_quality = legacy.use_paint_over_quality
        self.capture.update_tunables(settings)


class HevcCapture(PrivateLiveControls):
    def __init__(self):
        self.capture = runtime().ScreenCapture()

    def start_capture(self, legacy, callback):
        module = runtime()
        settings = module.CaptureSettings()
        for name in ("capture_width", "capture_height", "capture_x", "capture_y", "capture_cursor",
                     "target_fps", "scale", "auto_adjust_screen_capture_size", "use_cpu",
                     "use_paint_over_quality", "paint_over_trigger_frames", "damage_block_threshold",
                     "damage_block_duration", "watermark_location_enum"):
            setattr(settings, name, getattr(legacy, name))
        watermark = legacy.watermark_path
        settings.watermark_path = watermark.decode("utf-8") if isinstance(watermark, bytes) else watermark
        for name in ("crf", "paintover_crf", "paintover_burst_frames", "streaming_mode"):
            setattr(settings, "video_" + name, getattr(legacy, "h264_" + name))
        settings.codec = "h265"
        settings.use_wayland = False
        settings.video_fullframe = True
        # Main 8-bit 4:2:0 is the negotiated browser profile for this path.
        settings.video_fullcolor = False
        settings.video_bit_depth = 8
        settings.omit_stripe_headers = True
        settings.encode_node_index = legacy.vaapi_render_node_index
        if not settings.use_cpu and "h265" not in module.hardware_encoders(settings.encode_node_index):
            raise RuntimeError("Selected GPU has no H.265 encoder; using H.264")
        accepted = False
        pending = []
        first_frame = threading.Event()
        delivery_lock = threading.Lock()

        def deliver(frame):
            # The existing ACK/backpressure protocol uses a wrapping uint16 ID.
            frame_id = frame.frame_id & 65535
            data = packet(bytes(frame), frame_id, settings.capture_width, settings.capture_height)
            with delivery_lock:
                if accepted:
                    callback(data, frame_id)
                elif len(pending) < 120:
                    pending.append((data, frame_id))
                first_frame.set()

        try:
            self.capture.start_capture(deliver, settings)
            self._settings = settings
            if not first_frame.wait(8):
                raise RuntimeError("H.265 encoder produced no frame within 8 seconds")
            info = self.capture.stream_info() or {}
            if str(info.get("codec")).lower() != "h265" or (not settings.use_cpu and not info.get("hardware")):
                raise RuntimeError("H.265 hardware initialization failed: " + str(info.get("encoder_reason", info)))
            with delivery_lock:
                for data, frame_id in pending:
                    callback(data, frame_id)
                pending.clear()
                accepted = True
            self.capture.request_idr_frame()
        except Exception:
            self.capture.stop_capture()
            raise

    def stop_capture(self):
        self.capture.stop_capture()

    def request_idr_frame(self):
        self.capture.request_idr_frame()
